mapper.select:
SELECT s.stock_code AS stockCode, s.stock_name AS stockName, s.market AS market, s.sector AS sector FROM stocks s LEFT JOIN stock_info si ON s.stock_code = si.stock_code
(s.stock_name LIKE CONCAT(#{keyword}, '%') OR s.stock_code LIKE CONCAT(#{keyword}, '%'))
AND s.sector = #{sector}
ORDER BY COALESCE(si.market_cap, 0) DESC ORDER BY s.stock_name ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM stocks
(stock_name LIKE CONCAT(#{keyword}, '%') OR stock_code LIKE CONCAT(#{keyword}, '%'))
AND sector = #{sector}
